 let state,world,busy=false,disconnected=false,lastSyncedAt=0,speed=1,started=false,storageWarning='',memoryOnly=false,dialogTrigger=null,dialogRevision=0,toastTimer,timer,heartbeatTimer,selectedEvent=null,eventPanelMarkup='',storedProgress=0,pendingClockActive=null,serverBackup=null,pendingRestartRequest=null;
 const local=!transport;const ownerKey=KEY+':owner',tabId=crypto.randomUUID();let saveOwner=null,backups=null;const unlocked=new Map();
