 function renderClock(){const running=isRunning();$('#clock').textContent=`第 ${state.day+1} 天 · ${['上午','午后','夜晚'][state.timeSlot]}`;$('#time-state').textContent=state.gameOver?'已结束':running?`${speed}× 运行中`:'暂停中';$('#time-state').classList.toggle('paused',!running);if($('#rate-hint'))$('#rate-hint').textContent=`${RULES.secondsPerPeriod*RULES.periodsPerDay/speed}秒/天`;$('#day-progress').style.width=`${state.gameOver?100:(state.timeSlot+clock.fraction)/RULES.periodsPerDay*100}%`;$('.time-pill').title=`已完整运营 ${state.day} 天；每天结束扣除 1 天服务器租期。离线、后台和管理弹窗暂停。`;}

 function ownsSave(){try{return !local||memoryOnly||saveOwner?.isCurrent();}catch{return memoryOnly;}}
 function save(){if(!local||memoryOnly||!ownsSave())return;try{storage.setItem(KEY,JSON.stringify({state,speed,started,progressMs:clock.progressMs}));}catch{memoryOnly=true;storageWarning='浏览器无法保存。请保持本页打开，并在玩法说明导出存档。';}}
 function notify(message,error=false){clearTimeout(toastTimer);markup($('#toast-region')).html=`<div class="toast ${error?'error':''}">${error?'!':'✓'} ${esc(message)}</div>`;toastTimer=setTimeout(()=>markup($('#toast-region')).html='',4300);}
 const isRunning=()=>ownsSave()&&started&&!state.gameOver&&!disconnected&&!pendingRestartRequest&&!document.hidden&&!dialog.open;
