 function renderQuality(){for(const kind of ['mood','content']){const value=$('#'+kind),bar=$('#'+kind+'-bar');if(value)value.textContent=state[kind];if(bar){bar.style.width=state[kind]+'%';bar.parentElement.setAttribute('aria-valuenow',String(state[kind]));}}}
 function redraw(){const sum=summarize(state),ended=state.gameOver,board=$('.building-board');if(board){const count=state.gameOver?0:state.events.filter(e=>e.expiresDay>state.day).length;board.dataset.eventCount=String(count);board.setAttribute('aria-label',`社区公告建筑，查看全部 ${count} 件待处理事件`);board.title=`社区公告 · ${count} 件待处理事件`;}$('#station-name').textContent=state.name;$('#station-slogan').textContent=state.slogan||'';$('#station-slogan').hidden=!state.slogan;$('.station-summary').title=[state.name,state.slogan].filter(Boolean).join(' · ');$('#strategy-shortcut').title='经营方向 · '+STRATEGIES.find(v=>v.id===state.strategy).name;$('#strategy-shortcut').setAttribute('aria-label',$('#strategy-shortcut').title);$('.money').title=sum.difficulty==='challenge'?`每日维护 ${sum.maintenanceCost} 刀`:'小金库';markup($('#cash')).html=`${fmt(state.cash)} <small>刀</small>`;markup($('#members')).html=`${fmt(state.members)} <small>/ ${sum.capacity}</small>`;$('#lease').textContent=remaining();$('.lease').classList.toggle('urgent',state.serverDaysRemaining<=5);$('#clock').textContent=`第 ${state.day+1} 天 · ${['上午','午后','夜晚'][state.timeSlot]}`;$('#time-state').textContent=ended?'已结束':isRunning()?`${speed}× 运行中`:'暂停中';$('#time-state').classList.toggle('paused',!isRunning());$('#weather').textContent=['☀ 晴 · 适合相遇','☀ 午后 · 来杯咖啡','☾ 晚安 · 灯火未眠'][state.timeSlot];$('.playground').dataset.period=String(state.timeSlot);renderQuality();renderManagement();renderBuildingAccess();lifeView.update(state,started);$('#last-log').textContent=logText(state.logs.at(-1)?.text||'一台 1C1G 服务器，一盏灯，等第一位佬友到来。');$('#storage-warning').hidden=!storageWarning;$('#storage-warning').textContent=storageWarning.replace('新版试玩','新版进度');$('#welcome-sign').hidden=state.members>0;renderEvent();renderClock();world?.redraw();updateChat();}
 function renderBuildingAccess(){const progress=communityProgress(state);$('#community-level').textContent=`Lv.${progress.level}`;$('#community-level').title=progress.next?`达到 ${progress.next.members} 位佬友升至 Lv.${progress.next.level}，还差 ${progress.remaining} 位；本局等级不回退`:'本局已达到最高社区等级';for(const building of ['benefits','resources']){const status=activityStatus(state,building),button=$('.building-'+building),badge=button.querySelector('.building-access');button.classList.toggle('is-locked',!status.unlocked);button.dataset.unlocked=String(status.unlocked);const name=building==='benefits'?'福利羊毛':'资源荟萃';button.title=status.unlocked?name+' · 已开放':name+` · 社区 Lv.${status.requiredLevel} 开放，${status.requiredMembers} 位佬友`;button.setAttribute('aria-label',button.title+(status.unlocked?'，查看建筑活动':'，查看开放条件'));badge.hidden=true;badge.textContent='';}}
 function updateChat(){
  const bubble=$('#ambient-chat'),time=performance.now();
  const active=chatEnabled&&isRunning()&&state.members>0;
  if(!active){chatSchedule.clear();bubble.hidden=true;return;}
  const scene=$('#world').getBoundingClientRect(),viewport=$('#scene-scroll').getBoundingClientRect(),base=$('.playground').getBoundingClientRect();
  const blockers=$$('.scene-actor,.life-hud,.topbar,.resource-bar,.scene-topline,.management-bar,.side-nav,.event-panel:not([hidden]),.scene-footer,.journal-strip,#toast-region .toast').filter(e=>e.getClientRects().length).map(e=>e.getBoundingClientRect());
  const candidates=getCommunityActors(state,time,chatMotion.matches).map(actor=>({...actor,placement:placeChat(actor,{scene,viewport,blockers})})).filter(a=>a.placement);
  const message=chatSchedule.step(time,{active,candidates,timeSlot:state.timeSlot});
  if(!message){bubble.hidden=true;return;}
  const place=candidates.find(a=>a.id===message.speakerId)?.placement;
  if(!place){bubble.hidden=true;return;}
  if(bubble.textContent!==message.text){bubble.textContent=message.text;bubble.setAttribute('aria-label',`游戏角色闲聊：${message.text}`);}bubble.dataset.speaker=message.speakerId;
  bubble.style.left=`${place.left-base.left}px`;bubble.style.top=`${place.top-base.top}px`;bubble.style.setProperty('--chat-tail',`${place.tail}px`);bubble.hidden=false;
 }
 function updateChatToggle(){const button=$('[data-action="chatter"]');if(button){button.setAttribute('aria-pressed',String(chatEnabled));button.querySelector('span').textContent=chatEnabled?'场景闲聊：开':'场景闲聊：关';}}
