 function renderSceneActors(actors=getSceneActors(state,0,chatMotion.matches)){const root=$('#scene-actors'),marked=actors.filter(a=>a.marker),ids=new Set(marked.map(a=>a.id));for(const button of [...root.children])if(!ids.has(button.dataset.actorId))button.remove();for(const actor of marked){let button=[...root.children].find(b=>b.dataset.actorId===actor.id);const e=actor.eventId?state.events.find(e=>e.id===actor.eventId):null;const amount=actor.marker==='coin'?state.pendingSponsors.filter(s=>s.expiresDay>state.day).reduce((total,s)=>total+s.amount,0):0;if(!button){button=document.createElement('button');button.type='button';button.dataset.actorId=actor.id;button.className='scene-actor '+(actor.marker==='×'?'troublemaker-actor':actor.marker==='coin'?'sponsor-actor':actor.marker==='!'?'attention-actor':'question-actor');if(actor.eventId)button.dataset.sceneEvent=actor.eventId;else button.dataset.action='claim';markup(button).html=`<span class="actor-marker ${actor.marker==='×'?'trouble-marker':''}" aria-hidden="true">${actor.marker==='coin'?icon('coin'):actor.marker}</span><span class="actor-tip" aria-hidden="true">${actor.marker==='coin'?'领取赞助':actor.marker==='×'?'处理争论':actor.marker==='!'?'需要你决定':'听听佬友说'}</span>`;root.append(button);}const label=actor.marker==='coin'?`领取 ${amount} 刀`:actor.marker==='×'?'处理争论':e?.category==='world'?'世界事件':actor.marker==='!'?'有事找你':'点击交谈';if(button.dataset.label!==label){button.querySelector('.actor-tip').textContent=label;button.dataset.label=label;}button.style.left=`${actor.markerX/WORLD_WIDTH*100}%`;button.style.top=`${actor.markerY/WORLD_HEIGHT*100}%`;button.dataset.worldX=String(actor.x);button.dataset.worldY=String(actor.y);button.setAttribute('aria-label',actor.marker==='coin'?`领取富可敌国的赞助，共 ${amount} 刀，点击全部领取`:`${actor.marker==='×'?'处理捣乱事件':'处理'+(e?.category==='world'?'世界':'人物')+'事件'}：${e?.title||''}，第 ${(e?.createdDay??0)+1} 天，剩 ${(e?.expiresDay??state.day)-state.day} 天`);button.title=actor.marker==='coin'?'点击赞助人或金币，领取赞助':`点击人物或 ${actor.marker}，查看${e?.title||'事件'}`;}}

