 function eventMarkup(e,dialogMode=false){return `<div class="event-kind"><span>${icon(e.category==='world'?'globe':'bolt')} ${e.category==='world'?'世界事件':'人物事件'}</span><small>${state.events.length} 件待办</small></div><h3>${esc(communityText(e.title))}</h3><p>${esc(communityText(e.description))}</p><div class="event-choices">${e.options.map(o=>`<button data-event="${esc(e.id)}" data-option="${o.id}" ${o.cost>state.cash||state.gameOver?'disabled':''}><span>${esc(o.label)} ${icon('arrow')}</span><small>${esc(communityText(o.description))}</small></button>`).join('')}</div><div class="event-deadline">再过 ${e.expiresDay-state.day} 天失效${dialogMode?'':' · 计时继续'}</div>`;}
